+/* ─── Banners ─── */
+
+[class*="instui"] ._pendo-step-container-size {
+  container: pantoken-pendo-guide / inline-size;
+}
+
+[class~="instui-banner"],
+[class~="instui-banner-sea"] {
+  --_banner-icon-background: var(--instui-component-banner-violet-icon-background);
+  --_banner-icon-size: 2rem;
+
+  ._pendo-step-container-styles {
+    position: relative;
+    height: auto;
+    overflow: hidden;
+    border: var(--instui-component-banner-border-width)
+      var(--instui-component-banner-border-style) var(--instui-component-banner-border-color);
+    border-radius: var(--instui-component-banner-border-radius);
+    padding-block: var(--instui-component-banner-relaxed-padding-vertical);
+    padding-inline-start: calc(
+      var(--instui-component-banner-relaxed-padding-horizontal) + var(--_banner-icon-size) +
+        var(--instui-component-banner-relaxed-content-gap-horizontal)
+    );
+    padding-inline-end: calc(
+      var(--instui-component-banner-relaxed-padding-horizontal) +
+        var(--instui-component-base-button-medium-height) +
+        var(--instui-component-banner-close-button-margin-right)
+    );
+    color: var(--instui-component-banner-color);
+    background: var(--instui-component-banner-violet-background);
+
+    &::before,
+    &::after {
+      content: "";
+      position: absolute;
+      inset-block-start: var(--instui-component-banner-relaxed-padding-vertical);
+      inset-inline-start: var(--instui-component-banner-relaxed-padding-horizontal);
+      inline-size: var(--_banner-icon-size);
+      block-size: var(--_banner-icon-size);
+    }
+
+    &::before {
+      border-radius: var(--instui-component-banner-relaxed-icon-border-radius);
+      background: var(--_banner-icon-background);
+    }
+
+    &::after {
+      background: var(--instui-component-banner-icon-color);
+      mask: var(--instui-icon-megaphone) center / 1.125rem no-repeat;
+    }
+  }
+}
+
+[class~="instui-banner-sea"] {
+  --_banner-icon-background: var(--instui-component-banner-sea-icon-background);
+
+  ._pendo-step-container-styles {
+    background: var(--instui-component-banner-sea-background);
+  }
+}
+
+@container pantoken-pendo-guide (max-width: 30em) {
+  [class~="instui-banner"],
+  [class~="instui-banner-sea"] {
+    --_banner-icon-size: 1.5rem;
+
+    ._pendo-step-container-styles {
+      padding-block: var(--instui-component-banner-compact-padding-vertical);
+      padding-inline-start: calc(
+        var(--instui-component-banner-compact-padding-horizontal) + var(--_banner-icon-size) +
+          var(--instui-component-banner-compact-content-gap-horizontal)
+      );
+      padding-inline-end: calc(
+        var(--instui-component-banner-compact-padding-horizontal) +
+          var(--instui-component-base-button-medium-height) +
+          var(--instui-component-banner-close-button-margin-right)
+      );
+
+      &::before,
+      &::after {
+        inset-block-start: var(--instui-component-banner-compact-padding-vertical);
+        inset-inline-start: var(--instui-component-banner-compact-padding-horizontal);
+      }
+
+      &::before {
+        border-radius: var(--instui-component-banner-compact-icon-border-radius);
+      }
+    }
+  }
+}

 /* ─── Embedded alert ─── */
