{"filePath":"/Users/dwahl/Scripts/pantoken/docs/demos/pendo/style.css","content":".pendo-showcase {
  display: grid;
  gap: 1.5rem;
}

.pendo-example {
  min-inline-size: 0;
}

.pendo-example__label {
  margin: 0 0 0.5rem;
  color: var(--instui-component-text-muted-color);
  font: var(--instui-font-weight-bold) var(--instui-font-size-text-sm) / 1.5
    var(--instui-font-family-base);
}

.pendo-example ._pendo-step-container {
  position: relative;
  visibility: visible;
  inline-size: 100%;
}

.pendo-example ._pendo-step-container-size {
  position: relative;
  visibility: visible;
  inline-size: 100%;
}

.pendo-example ._pendo-backdrop {
  display: none;
}

.pendo-example ._pendo-step-container-styles {
  box-sizing: border-box;
}

.pendo-example [data-component="title"] h2,
.pendo-example [data-component="text"] p {
  margin: 0;
}

.pendo-example .pendo-mock-flexbox-element + .pendo-mock-flexbox-element {
  margin-inline-start: var(--instui-component-base-button-gap-button-content-md);
}

.pendo-example .pendo-tooltip-caret--top {
  border-inline: 16px solid transparent;
  border-block-start: 16px solid var(--instui-component-view-background-primary);
  position: absolute;
  inset-block-end: -11px;
  inset-inline-start: 2rem;
  z-index: 11;
}

.pendo-example .pendo-tooltip-caret-border {
  border-inline: 17px solid transparent;
  border-block-start: 17px solid var(--instui-component-popover-border-color);
  position: absolute;
  inset-block-end: -12px;
  inset-inline-start: calc(2rem - 1px);
  z-index: 10;
}

@media (min-width: 64rem) {
  .pendo-showcase {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: start;
  }
}
"}

